from pathlib import Path
import json,hashlib
base=Path('data/patch-api/evidence/3.0.2-session-2026-10-09')
results={}
for name in ['seals.json','closure-seals.json','receipt-seals.json']:
    seals=json.loads((base/name).read_text())
    failures=[p for p,h in seals.items() if hashlib.sha256((base/p).read_bytes()).hexdigest()!=h]
    results[name]={'sealed_files':len(seals),'failures':failures}
print(json.dumps(results,sort_keys=True))
assert all(not r['failures'] for r in results.values())
